import{_ as p,o as e,c as a,a as t}from"./app.c84298d3.js";const c={},r=t('<h1 id="\u110B\u116D\u11A8\u1109\u1175\u11B7\u110B\u1173\u11AF-\u1107\u1165\u1105\u1175\u110C\u1161" tabindex="-1"><a class="header-anchor" href="#\u110B\u116D\u11A8\u1109\u1175\u11B7\u110B\u1173\u11AF-\u1107\u1165\u1105\u1175\u110C\u1161" aria-hidden="true">#</a> \uC695\uC2EC\uC744 \uBC84\uB9AC\uC790</h1><p>\uC694\uC998 \uB2E4\uC591\uD55C \uACE0\uBBFC\uC744 \uCC38 \uB9CE\uC774 \uD558\uACE0 \uC788\uB2E4. \uC138\uC0C1\uC774 \uBCC0\uD654\uD558\uB294 \uC18D\uB3C4\uAC00 \uB0B4 \uC0DD\uAC01\uBCF4\uB2E4 \uD6E8\uC52C \uBE60\uB974\uACE0, \uBCC0\uD654\uC758 \uC18D\uB3C4\uB294 \uB530\uB77C\uAC00\uAE30\uAC00 \uC810\uC810 \uBC85\uCC28\uACE0, AI(\uD639\uC740 \uC720\uD29C\uBE0C\uB098 \uC778\uC2A4\uD0C0) \uB54C\uBB38\uC5D0 \uB3C4\uD30C\uBBFC\uC5D0 \uC808\uC5EC\uC9C0\uBA74\uC11C \uC810\uC810 \uBA4D\uCCAD\uD574\uC9C0\uB294 \uC911\uC774\uB2E4. \uADF8\uB7F0\uB370 \uC5F0\uCC28\uAC00 \uC313\uC77C\uC218\uB85D \uD574\uACB0\uD574\uC57C \uD558\uB294 \uBB38\uC81C\uC758 \uB09C\uC774\uB3C4\uB294 \uB192\uC544\uC9C4\uB2E4. \uC5B4\uB5BB\uAC8C \uC0B4\uC544\uC57C \uC88B\uC744\uAE4C? \uC5B4\uB5A4 \uD0DC\uB3C4\uB97C \uAC00\uC838\uC57C \uC88B\uC744\uAE4C?</p><p>\uC77C\uC740 \uBCF8\uC758\uC544\uB2C8\uAC8C \uC80A\uC744 \uB54C \uC2DC\uC791\uD588\uB2E4. \uB300\uD559\uAD50 \uC878\uC5C5 \uC804\uC5D0\uB294 \uACE0\uB4F1\uD559\uAD50\uC5D0\uC11C \uAC15\uC0AC\uB85C \uC77C\uC744 \uD558\uAE30\uB3C4 \uD588\uACE0, \uD504\uB9AC\uB79C\uC11C\uB85C \uC6F9\uC0AC\uC774\uD2B8\uB97C \uB9CC\uB4E4\uAE30\uB3C4 \uD558\uACE0, \uAD70\uB300 \uC804\uC5ED \uD6C4\uC5D0 \uCDE8\uC5C5\uD588\uB358 \uB514\uC790\uC778 \uC5D0\uC774\uC804\uC2DC \uD68C\uC0AC\uC5D0\uC11C\uB3C4 \uADF8\uB204\uBCF4\uB4DC/\uC6CC\uB4DC\uD504\uB808\uC2A4 \uAE30\uBC18\uC758 \uC6F9 \uD398\uC774\uC9C0\uB97C \uB2E4\uC218 \uB9CC\uB4E4\uC5C8\uB2E4. \uADF8\uB7EC\uB2E4 \uB300\uD559\uAD50 \uB9C9\uD559\uAE30\uC5D0 \uC90C\uC778\uD130\uB137(\uD604 \uC774\uC2A4\uD2B8\uC5D0\uC774\uB4DC)\uC5D0 \uCDE8\uC5C5\uD558\uC5EC 2\uB144 6\uAC1C\uC6D4, \uC774\uD6C4 \uB124\uC774\uBC84\uC5D0\uC11C 3\uB144 6\uAC1C\uC6D4, \uADF8\uB9AC\uACE0 \uD604\uC7AC \uD1A0\uC2A4 \uD50C\uB808\uC774\uC2A4\uC5D0 \uC785\uC0AC\uD55C\uC9C0 9\uAC1C\uC6D4 \uC815\uB3C4?</p><p>\uC5EC\uD2BC \uC774\uC81C 7\uB144\uCC28 \uAC1C\uBC1C\uC790\uAC00 \uB418\uC5C8\uB2E4(\uB300\uD559\uAD50 \uC7AC\uD559\uC2DC\uC808 \uC77C\uD588\uB358 \uAE30\uAC04\uAE4C\uC9C0 \uD3EC\uD568\uD558\uBA74 9\uB144\uCC28\uB77C\uACE0 \uD560 \uC218 \uC788\uC73C\uB824\uB098?). \uADFC\uB370 \uADF8\uAC8C \uAF64 \uBD80\uB044\uB7FD\uB2E4. \uC544\uBB34\uB9AC \uC0DD\uAC01\uD574\uB3C4 \uB098\uB294 7\uB144\uCC28\uC758 \uC5ED\uB7C9\uC744 \uAC16\uCD94\uC9C0 \uBABB\uD588\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</p><p>\uD2B9\uC815 \uC5F0\uCC28\uC758 \uC5ED\uB7C9\uC774\uB77C\uB294 \uAC8C \uB531 \uB9DE\uAC8C \uC815\uD574\uC838\uC788\uC9C0\uB294 \uC54A\uACA0\uC9C0\uB9CC, \uB0B4\uAC00 \uC0DD\uAC01\uD558\uAE30\uC5D0 7\uB144\uCC28\uB294 \u201C\uC815\uB2F5\uC774 \uB69C\uB837\uD558\uC9C0 \uC54A\uC740 \uAE30\uC220\uC801 \uBB38\uC81C\uB97C \uCD94\uC0C1\uD654\uD560 \uC218 \uC788\uB294 \uC5ED\uB7C9\u201D\uC744 \uAC16\uCD94\uC5B4\uC57C \uD55C\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</p><p>\uB0B4 \uCEE4\uB9AC\uC5B4\uB97C \uB3CC\uC544\uBCF4\uBA74 \uB098\uB294 \uB300\uCCB4\uB85C \u201C\uC120\uBC30 \uAC1C\uBC1C\uC790\uAC00 \uB9CC\uB4E4\uC5B4\uB193\uC740 \uC124\uACC4 \uD639\uC740 \uD658\uACBD\u201D \uC704\uC5D0\uC11C \uC791\uC5C5\uC744 \uC9C4\uD589\uD588\uB2E4. \uC90C\uC778\uD130\uB137\uC5D0 \uC788\uC744 \uB54C\uC5D0\uB3C4, \uC120\uBC30 \uAC1C\uBC1C\uC790\uAC00 \uC124\uACC4\uD55C \uD2C0\uC744 \uADF8\uAC8C \uBC97\uC5B4\uB098\uC9C0 \uC54A\uC740 \uD615\uD0DC\uB85C \uAC1C\uBC1C\uC744 \uC9C4\uD589\uD588\uACE0, \uB124\uC774\uBC84\uC5D0 \uC788\uC744 \uB54C\uC5D0\uB3C4 \uC124\uACC4\uC758 \uC138\uBD80\uC0AC\uD56D\uC740 \uCC44\uC6CC\uB098\uAC14\uC9C0\uB9CC \uD070 \uD2C0\uC740 \uD14C\uD06C\uB9AC\uB4DC\uAC00 \uC124\uACC4\uD55C \uB0B4\uC6A9\uC744 \uD1A0\uB300\uB85C \uAC1C\uBC1C\uD588\uB2E4. \uC9C0\uAE08\uB3C4 \uD06C\uAC8C \uB2E4\uB974\uC9C0 \uC54A\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4. \uC774\uBBF8 \uC5EC\uB7EC\uAC00\uC9C0 \uC5ED\uACBD\uACFC \uC2E4\uD328\uB97C \uD1B5\uD574 \uAC16\uCD94\uC5B4\uC9C4 \uC124\uACC4\uC640 \uD1A0\uB300, \uD50C\uB7AB\uD3FC \uC704\uC5D0 \uBB34\uC5B8\uAC00\uB97C \uB9CC\uB4DC\uB294 \uC911\uC774\uB2E4.</p><p>\uB098\uB294 \uBAA8\uBC29\uC744 \uC798 \uD55C\uB2E4. \uC774\uBBF8 \uC798 \uAC16\uCD94\uC5B4\uC9C4 \uD658\uACBD\uC744 \uD655\uC7A5\uD558\uAC70\uB098 \uC774\uBBF8 \uD480\uC774\uB41C \uBB38\uC81C\uC5D0\uC11C \uD55C \uAC78\uC74C \uB354 \uB098\uC544\uAC00\uB294 \uAC83\uC740 \uACE7\uC798 \uD558\uB294 \uD3B8\uC774\uB2E4. \uB2E4\uB978 \uAD00\uC810\uC5D0\uC11C \uBCF4\uBA74, \uB098 \uC2A4\uC2A4\uB85C \uBAA8\uD638\uD558\uACE0 \uC5B4\uB824\uC6B4 \uBB38\uC81C\uC758 \uD574\uACB0\uCC45\uC744 \uCC3E\uC544\uB0B4\uB294 \uAC83\uC740 \uBB34\uCC99 \uC5B4\uB824\uC6CC\uD55C\uB2E4. \uBB3C\uB860 \uADF8\uAC78 \uC27D\uAC8C \uD558\uB294 \uC0AC\uB78C\uC740 \uD754\uCE58 \uC54A\uB2E4. \uD558\uC9C0\uB9CC \uADF8\uB7F0 \uC0AC\uB78C\uC740 \uBD84\uBA85 \uC874\uC7AC\uD55C\uB2E4.</p><p>\uC800\uC5F0\uCC28\uC77C \uB54C\uC5D0\uB294 \u201C\uC624 \uB098 \uC880 \uC798 \uD558\uB294 \uD3B8\uC774\uB124?\u201D \uB77C\uACE0 \uC0DD\uAC01\uD588\uC9C0\uB9CC, \uADF8 \uD2C0\uC744 \uD06C\uAC8C \uBC97\uC5B4\uB098\uC9C0 \uBABB\uD558\uB294 \uC911\uC774\uB2E4. \uD55C\uACC4\uC5D0 \uBD80\uB52A\uD614\uB2EC\uAE4C?</p><p>\uC0AC\uC2E4 \uC695\uC2EC\uC774\uB2E4.</p><p>\uB300\uBD80\uBD84\uC758 \uBB38\uC81C\uD574\uACB0\uC740 \uBAA8\uBC29\uC5D0\uC11C \uC2DC\uC791\uD55C\uB2E4. \uC774\uBBF8 \uD574\uACB0\uB41C \uBB38\uC81C\uC704\uC5D0 \uBB34\uC5B8\uAC00\uB97C \uACC4\uC18D \uB367\uBD99\uC774\uB294 \uAC83\uC774\uB2E4. \uC774\uB807\uAC8C\uB3C4 \uC2DC\uB3C4\uD574\uBCF4\uACE0, \uC800\uB807\uAC8C\uB3C4 \uC2DC\uB3C4\uD574\uBCF4\uACE0, \uACC4\uC18D \uC870\uBB3C\uC870\uBB3C \uD558\uBA74\uC11C \uAD50\uC815\uD558\uB294 \uAC83\uC774\uB2E4. \uC9C0\uB984\uAE38\uC740 \uC5C6\uB2E4.</p><p>\uADFC\uB370 \uC694\uC998 \uACC4\uC18D \uC9C0\uB984\uAE38\uC744 \uACC4\uC18D \uCC3E\uC73C\uB824\uACE0 \uD55C\uB2E4. \uB9C8\uC74C\uC774 \uC870\uAE09\uD574\uC9C4\uB2E4. \uB098\uB294 \uB611\uB611\uD55C \uD3B8\uB3C4 \uC544\uB2C8\uACE0 \uCC3D\uC758\uC801\uC778 \uD3B8\uB3C4 \uC544\uB2C8\uACE0, \uB2E4\uC7AC\uB2E4\uB2A5\uD55C \uD3B8\uB3C4 \uC544\uB2C8\uB2E4. \uC5B8\uC81C\uB098 \uB098\uB294 \uB0B4 \uD55C\uACC4\uB97C \uBA85\uD655\uD788 \uC54C\uACE0 \uC788\uB2E4. \uC77C\uB2E8 \u201C\uC9C0\uAE08\uC740\u201D \uBABB\uD558\uB294 \uAC83\uB4E4\uC774 \uAF64 \uB9CE\uB2E4.</p><p>\uADF8\uB7F0\uB370 \uC2DC\uAC04\uC774 \uD750\uB974\uACE0, \uACBD\uB825\uC774 \uC313\uC774\uACE0, \uC694\uAD6C\uB418\uB294 \uC5ED\uB7C9\uC774 \uB9CE\uC544\uC9C8\uC218\uB85D \uB9C8\uC74C\uC774 \uC870\uAE09\uD574\uC9C4\uB2E4. \uC774\uAC83\uB3C4 \uC798 \uD574\uC57C \uD558\uACE0, \uC800\uAC83\uB3C4 \uC798 \uD574\uC57C \uD55C\uB2E4. \uB9C8\uC8FC\uD558\uAC8C \uB418\uB294 \uC0AC\uB78C\uC774 \uB9CE\uC544\uC9C0\uACE0, \uC0AC\uB78C\uB4E4\uC758 \uBE5B\uB098\uB294 \uC7AC\uB2A5\uC774 \uB208\uC5D0 \uBCF4\uC778\uB2E4. \uB098\uB294 \uC800\uB807\uAC8C \uD558\uACE0 \uC2F6\uC5B4\uB3C4 \uC798 \uC548 \uB41C\uB2E4. \uC800 \uC0AC\uB78C\uB4E4\uC774 \uBD80\uB7FD\uB2E4.</p><p>\uC774 \uB610\uD55C \uC695\uC2EC\uC774\uB2E4. \uB0B4\uAC00 \uAC00\uC9C0\uC9C0 \uBABB\uD55C \uAC83\uC5D0 \uB300\uD574 \uBD80\uB7EC\uC6CC \uD574\uB3C4 \uB2EC\uB77C\uC9C0\uB294 \uAC83\uC740 \uC5C6\uB2E4. \uADF8\uB0E5 \uB0B4\uAC00 \uD560 \uC218 \uC788\uB294 \uAC83\uC744 \uD574\uC57C\uD55C\uB2E4.</p><p>\uADF8\uB798\uC11C \uB098\uB294 \uB0A8\uB4E4\uBCF4\uB2E4 \uC2DC\uAC04\uC744 \uB9CE\uC774 \uC368\uC57C \uB41C\uB2E4. \uBB34\uC5B8\uAC00\uB97C \uBC18\uBCF5\uD558\uB2E4 \uBCF4\uBA74 \uC775\uC219\uD574\uC9C0\uACE0, \uC775\uC219\uD574\uC9C0\uBA74 \uD3B8\uC548\uD574\uC9C0\uACE0, \uD3B8\uC548\uD574\uC9C4 \uC0C1\uD0DC\uAC00 \uB418\uC5B4\uC57C \uC81C\uB300\uB85C \uC0DD\uAC01\uD560 \uC218 \uC788\uB2E4. \uCF54\uB529\uC774\uB77C\uB294 \uD589\uC704\uAC00 \uC775\uC219\uD574\uC838\uC57C \uCF54\uB529\uC744 \uD558\uBA74\uC11C \uB354 \uAE4A\uC740 \uC124\uACC4\uC5D0 \uB300\uD574 \uC0DD\uAC01\uD560 \uC218 \uC788\uAC8C \uB418\uB294 \uAC83 \uCC98\uB7FC. \uADF8\uB9AC\uACE0 \uC0DD\uAC01\uC744 \uD558\uB2E4\uBCF4\uBA74 \uBB34\uC5C7\uC774 \uC911\uC694\uD55C\uC9C0 \uBCF8\uC9C8\uC774 \uBB34\uC5C7\uC778\uC9C0 \uC870\uAE08\uC529 \uC54C\uC544\uAC08 \uC218 \uC788\uB2E4.</p><p>\uB098\uB294 \uADF8\uB7F0 \uC0AC\uB78C\uC774\uB2E4. \uC870\uAE08 \uB290\uB9B0 \uC0AC\uB78C. \uC5F0\uC2B5\uC744 \uB9CE\uC774 \uD574\uC57C \uB418\uB294 \uC0AC\uB78C. \uB300\uC2E0 \uCCB4\uB825\uC774 \uC88B\uC740 \uD3B8\uC774\uACE0 \uC131\uC2E4\uD55C \uD3B8\uC774\uB2E4. \uADF8\uB0E5 \uC774\uB807\uAC8C \uC0B4\uC544\uC654\uAE30 \uB54C\uBB38\uC5D0 \uCCB4\uB825\uC774 \uC88B\uC544\uC9C4\uAC78\uAE4C? \uADF8\uAC74 \uC798 \uBAA8\uB974\uACA0\uB2E4. \uC5B4\uCA0C\uB4E0 \uC9C0\uAE08\uC740 \uADF8\uB807\uB2E4.</p><p>\uADF8\uB798\uC11C \uB0B4 \uCEE4\uB9AC\uC5B4\uB294 \uC5B4\uB5BB\uAC8C \uC313\uC544\uAC00\uC57C \uC88B\uC744\uAE4C?</p><p>\uC695\uC2EC\uC744 \uBC84\uB9AC\uC790. \uB2E4 \uC798 \uD558\uACE0 \uC2F6\uC740 \uC695\uC2EC\uC744 \uBC84\uB9AC\uC790. \uD55C \uAC00\uC9C0\uB9CC \uC798 \uD574\uB3C4 \uB41C\uB2E4. \uC544\uB2C8, \uD55C \uAC00\uC9C0\uB77C\uB3C4 \uC77C\uB2E8 \uC798 \uD574\uC57C \uD55C\uB2E4.</p><p>\uB098\uB294 \uD06C\uAC8C \uCD94\uC0C1\uD654 \uD558\uB294 \uB2A5\uB825\uC774 \uC57D\uD55C \uD3B8\uC774\uB2E4. \uADF8\uCE58\uB9CC \uC791\uAC8C \uCD94\uC0C1\uD654 \uD558\uB294 \uB2A5\uB825\uC740 \uB098\uC058\uC9C0 \uC54A\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4. \uC791\uC740 \uAC83\uB4E4\uC744 \uBAA8\uC73C\uB2E4\uBCF4\uBA74 \uD070 \uAC83\uB3C4 \uC870\uAE08\uC529 \uB9CC\uB4E4 \uC218 \uC788\uB2E4. \uC791\uC740 \uB2E8\uC704\uC758 \uCF54\uB4DC\uB97C \uAC1C\uC120\uD558\uACE0, \uADF8\uAC83\uB4E4\uC744 \uD55C \uB208\uC5D0 \uBAA8\uC544 \uBCF4\uB2E4\uAC00 \uD070 \uB2E8\uC704\uC758 \uCF54\uB4DC\uB3C4 \uAC1C\uC120\uD558\uB2E4\uBCF4\uBA74 \u201C\uC544\uD0A4\uD14D\uD2B8\u201D \uC758 \uC601\uC5ED\uC5D0 \uC870\uAE08\uC774\uB098\uB9C8 \uB3C4\uB2EC\uD560 \uC218 \uC788\uC9C0 \uC54A\uC744\uAE4C?</p><p>\uC88B\uC740 \uC124\uACC4\uB294 \uC798 \uBAA8\uB974\uACA0\uB2E4. \uD574\uBCF8\uC801\uC774 \uC5C6\uC73C\uB2C8\uAE4C. \uADF8\uCE58\uB9CC \uC88B\uC740 \uC124\uACC4\uB97C \uD558\uACE0 \uC2F6\uB2E4. \uC88B\uC740 \uC124\uACC4\uAC00 \uBB34\uC5C7\uC778\uC9C0 \uBAA8\uB974\uAE30 \uB54C\uBB38\uC5D0 \uC88B\uC740 \uC124\uACC4\uB97C \uD558\uB294 \uAC83\uC740 \uC5B4\uB835\uB2E4. \uADF8\uB798\uC11C \uACC4\uC18D \uACBD\uD5D8\uD574\uC57C \uD55C\uB2E4. \uB9CC\uB4E4\uACE0 \uAC08\uC544 \uC5CE\uACE0, \uB9CC\uB4E4\uACE0 \uAC08\uC544 \uC5CE\uB294 \uD589\uC704\uB97C \uACC4\uC18D \uD574\uBD10\uC57C \uD55C\uB2E4. \uC9C0\uB984\uAE38\uC740 \uC5C6\uB2E4.</p><p>\uADF8\uB798, \uC9C0\uB984\uAE38\uC740 \uC5C6\uB2E4. \uADF8\uB0E5 \uD55C \uAC78\uC74C\uC529 \uB098\uC544\uAC00\uC790. \uC313\uC544\uAC00\uC790. \uADF8\uB7EC\uB2E4\uBCF4\uBA74 \uB3C4\uB2EC\uD560 \uC218 \uC788\uC744 \uAC83\uC774\uB2E4.</p><p>\uC544 \uADF8\uB9AC\uACE0 \uAE30\uB85D\uD558\uC790. \uBC1C\uC0B0\uD558\uC790. \uADF8\uAC8C \uB098\uC758 \uD655\uC2E4\uD558\uACE0 \uC548\uC804\uD55C \uC790\uC0B0\uC774 \uB420 \uAC83\uC774\uB2E4.</p>',21),n=[r];function o(_,s){return e(),a("div",null,n)}var i=p(c,[["render",o],["__file","index.html.vue"]]);export{i as default};
